Here is the canonical sketch for reading potentiometer telemetry:

```cpp
const int potPin = A0; // Center wiper connected to A0

void setup() {
  Serial.begin(9600); // Initialize telemetry communication
}

void loop() {
  int rawValue = analogRead(potPin);         // Read ADC count (0 to 1023)
  float voltage = rawValue * (5.0 / 1023.0); // Convert to true voltage

  Serial.print("ADC Count: ");
  Serial.print(rawValue);
  Serial.print(" | Voltage: ");
  Serial.print(voltage, 2);
  Serial.println(" V");

  delay(200); // 5 Hz telemetry cadence for human readability
}
```

Open the Serial Monitor at 9600 baud. As you rotate the potentiometer shaft clockwise and counterclockwise, watch the values glide smoothly between `0` and `1023`!
